<?php declare(strict_types=1); require_once dirname(__DIR__,2).'/lib/tool-page.php'; $tool=['title'=>'Free Discount Calculator Online','description'=>'Calculate discount amount and final sale price instantly.','url'=>'https://smarttoolz.in/tools/discount-calculator/']; smarttoolz_tool_page_start($tool); ?><main class="tool-page"><section class="tool-intro"><span class="tool-kicker">DISCOUNT CALCULATOR</span><h1>Discount Calculator</h1><p>Find the discount amount and final price in seconds.</p></section><section class="tool-workspace"><div class="tool-panel"><label>Original price<input id="p" type="number" min="0" step="0.01" placeholder="2500"></label><label>Discount %<input id="d" type="number" min="0" max="100" step="0.1" placeholder="20"></label><button id="go" class="tool-btn">Calculate Discount</button><p id="out" style="margin-top:15px;font-size:18px;font-weight:800"></p></div></section></main><script>(()=>{const $=id=>document.getElementById(id);$('go').onclick=()=>{let p=+$('p').value,d=+$('d').value;if(!Number.isFinite(p)||!Number.isFinite(d)||p<0||d<0||d>100){$('out').textContent='Enter valid values.';return}let s=p*d/100;$('out').textContent=`You save: ${s.toFixed(2)} · Final price: ${(p-s).toFixed(2)}`}})();</script><?php smarttoolz_tool_page_end(); ?>